    public function index()
    {
        if(!CompanyRequestScope::sealedFor($this)){show_error('Contexto de empresa indisponível.',503);return;}require_once APPPATH.'services/CompanyInvoiceConnectNotification.php';require_once APPPATH.'services/CompanyConnectInstanceOperations.php';require_once APPPATH.'services/CompanyConnectPairing.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$config=new CompanyConnectApi($this->db,db_prefix());$service=new CompanyInvoiceConnectNotification($this->db,db_prefix());$this->output->set_header('Cache-Control: no-store')->set_header('Pragma: no-cache')->set_header('Referrer-Policy: no-referrer');$url=CompanyRequestScope::adminUrl($this,'company_connect_api');$csrf=$this->session->userdata('company_connect_api_csrf');if(!is_string($csrf)||!preg_match('/^[a-f0-9]{64}$/D',$csrf)){$csrf=bin2hex(random_bytes(32));$this->session->set_userdata('company_connect_api_csrf',$csrf);}$qrCredential=null;$error=null;$invoice=0;$after=0;$afterValue=$this->input->get('after',false);if($afterValue!==null){if(!is_string($afterValue)||!preg_match('/^[1-9][0-9]{0,8}$/D',$afterValue)){show_error('Página inválida.',422);return;}$after=(int)$afterValue;}$query=$this->input->get('invoice',false);if($query!==null){if(!is_string($query)||!preg_match('/^[1-9][0-9]{0,8}$/D',$query)){show_error('Documento inválido.',422);return;}$invoice=(int)$query;}
        try{$profile=$config->page($issuer,$actor);$this->load->library('encryption');$encrypt=fn($v)=>$this->encryption->encrypt($v);$decrypt=fn($v)=>$this->encryption->decrypt($v);$method=$this->input->method(true);if($method==='POST'){$posted=$this->input->post('company_connect_api_csrf',false);if(!is_string($posted)||!hash_equals($csrf,$posted)){show_error('Reabra a página antes de continuar.',403);return;}$action=$this->input->post('action',false);$revision=$this->input->post('revision',false);if(!is_string($revision)||!preg_match('/^(0|[1-9][0-9]{0,8})$/D',$revision))throw new DomainException('company_connect_api_invalid');
                if($action==='save'){$endpoint=$this->input->post('endpoint_id',false);$instance=$this->input->post('instance_name',false);$token=$this->input->post('instance_token',false);if(!is_string($endpoint)||!is_string($instance)||!is_string($token))throw new DomainException('company_connect_api_invalid');$config->save($issuer,$actor,(int)$revision,$endpoint,$instance,$token,$encrypt);}
